# Generated by build.py from recipe.yml for recipe surl-hand-bound-ports-to-the-app. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site', 'site2' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/greeting.txt'), "Welcome aboard.`n")
[IO.File]::WriteAllText((Join-Path $PWD 'site2/greeting.txt'), "Welcome aboard.`n")
[IO.File]::WriteAllText((Join-Path $PWD 'run-tests.sh'), "#!/bin/sh`n# Starts surl on free ports, hands the bound URLs to the app, and checks what surl recorded.`n# SITE names the directory to serve; it defaults to site.`nout=`$(mktemp)`nlog=`$(mktemp)`nsurl -v --directory `"`${SITE:-site}`" --mail-domain example.com --mailbox app@example.com:secret \`n  http://127.0.0.1:0/ smtp://127.0.0.1:0/ > `"`$out`" 2> `"`$log`" &`nsurl_pid=`$!`ntrap 'kill `$surl_pid 2>/dev/null; rm -f `"`$out`" `"`$log`"' EXIT`n`n# surl writes one Listening on line per listen URL once every listener has bound.`n# If surl exits first, it refused to start: show why and stop with its exit code.`nuntil [ `"`$(grep -c '^Listening on ' `"`$out`")`" -eq 2 ]; do`n  kill -0 `$surl_pid 2>/dev/null || { wait `$surl_pid; code=`$?; cat `"`$log`" >&2; exit `$code; }`n  sleep 0.1`ndone`n`nAPP_HTTP_URL=`$(sed -n 's|^Listening on \(http://.*\)`$|\1|p' `"`$out`")`nAPP_SMTP_URL=`$(sed -n 's|^Listening on \(smtp://.*\)`$|\1|p' `"`$out`")`nexport APP_HTTP_URL APP_SMTP_URL`necho `"the app gets `$APP_HTTP_URL and `$APP_SMTP_URL`"`nsh app.sh || exit`n`n# What surl recorded: its log notes each message it stored, on its own time, so wait for the`n# line for at most 10 s first.`ni=0; until grep -q 'Message stored: ' `"`$log`"; do i=`$((i+1)); [ `$i -ge 100 ] && break; sleep 0.1; done`ngrep -o 'Message stored: .*' `"`$log`"`n")
[IO.File]::WriteAllText((Join-Path $PWD 'app.sh'), "#!/bin/sh`n# Stands in for the app under test: it finds both servers through the environment alone.`ngreeting=`$(curl -fsS `"`${APP_HTTP_URL}greeting.txt`") || exit`nprintf 'Subject: Welcome\r\n\r\n%s\r\n' `"`$greeting`" |`n  curl -sS -u app@example.com:secret --mail-from app@example.com --mail-rcpt app@example.com \`n    -T - `"`${APP_SMTP_URL}example.com`" || exit`necho `"the app mailed: `$greeting`"`n")
[IO.File]::WriteAllText((Join-Path $PWD 'run-twice.sh'), "#!/bin/sh`n# Runs the tests twice at once, the first serving directory `$1 and the second `$2.`nSITE=`$1 sh run-tests.sh > run1.txt 2>&1 &`nfirst=`$!`nSITE=`$2 sh run-tests.sh > run2.txt 2>&1 &`nsecond=`$!`nwait `$first; a=`$?`nwait `$second; b=`$?`nif [ `$a -le `$b ]; then echo `"exit codes: `$a `$b`"; else echo `"exit codes: `$b `$a`"; fi`nif [ `$a -eq 0 ] && [ `$b -eq 0 ] && [ `"`$(head -n 1 run1.txt)`" != `"`$(head -n 1 run2.txt)`" ]; then`n  echo `"each run got its own ports`"`nfi`ngrep -h -o 'is in use by another surl process' run1.txt run2.txt || true`n")
sh run-tests.sh
